// ————— "A block for your tower" — the notice when blocks are laid —————
// HAND-MAINTAINED. Not generated by build-vite-app.py.
//
// Lloyd, Oct 15 2026: "we need to let users know when they've received a
// block." lib/blocks.js announces every block this device lays (LAID_EVENT);
// this shows it, quietly, at the foot of the screen, and goes by itself.
//
// The journey's rules hold here too:
//   · effort only — the line says what was DONE, never how well
//   · no counts — several blocks at once read "New blocks for your tower" and
//     show the blocks themselves, never a number
//   · nothing to chase — no "next", no progress toward a building
//   · color is never alone — every mark carries its glyph
// It is polite (aria-live), never steals focus, and with reduced motion it
// simply appears.

import { useEffect, useRef, useState } from "react";
import { T, ACCENT } from "./tokens.js";
import { LAID_EVENT } from "./blocks.js";

const MARK = {
  hiragana: ["あ", ACCENT.hiragana, "Hiragana"], katakana: ["ア", ACCENT.katakana, "Katakana"],
  kanji: ["漢", ACCENT.kanji, "Kanji"], grammar: ["文", ACCENT.grammar, "Grammar"],
  vocabulary: ["言", ACCENT.vocabulary, "Vocabulary"], checker: ["直", ACCENT.checker, "Checker"],
};

function line(b) {
  const name = MARK[b.source]?.[2] || "";
  switch (b.action) {
    case "lesson": return `For finishing a lesson — ${name}`;
    case "review": return `For finishing a review — ${name}`;
    case "check":  return "For checking a sentence";
    case "login":  return "For showing up today";
    case "stage":  return `For finishing ${b.label || "a stage"}`;
    default:       return "";
  }
}

function Mini({ b }) {
  const m = MARK[b.source];
  const glyph = b.action === "review" ? "復" : m?.[0];
  const stage = b.action === "stage";
  return (
    <span aria-hidden="true" style={{
      width: 30, height: 20, borderRadius: 3, flexShrink: 0, display: "inline-flex", alignItems: "center", justifyContent: "center",
      background: stage ? "linear-gradient(180deg,#C9A24A 0 18%,#8A6A22 18% 24%,#7E5A38 24%)" : "#C9A47C",
      boxShadow: "inset 0 1px 0 rgba(255,255,255,.4),0 2px 0 var(--ts-block-lip)",
    }}>
      {glyph && b.action !== "login" && !stage && (
        <span style={{ width: 13, height: 13, borderRadius: 2, background: m[1], color: "#FFF8EC",
                       font: `700 10px/13px ${T.jpFont}`, textAlign: "center" }}>{glyph}</span>
      )}
    </span>
  );
}

const CSS = `
.tbn{position:fixed;left:50%;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:40;transform:translateX(-50%);
  width:calc(100% - 32px);max-width:420px;box-sizing:border-box;display:flex;align-items:center;gap:12px;padding:10px 8px 10px 14px;
  border-radius:14px;color:#2C2A26;background:#FBF7EE;box-shadow:inset 0 0 0 1.5px #D9CFB8,0 6px 18px rgba(44,42,38,.18);
  animation:tbn-in .28s ease-out both}
@keyframes tbn-in{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}
.tbn button{min-height:44px;border:0;background:transparent;cursor:pointer;font:700 .8125rem var(--ts-ui);color:#2C2A26;border-radius:10px;padding:0 10px}
.tbn button:focus-visible{outline:3px solid var(--ts-ring);outline-offset:2px}
@media (prefers-reduced-motion:reduce){.tbn{animation:none}}
`;

const SHOW_MS = 5000;

export default function BlockNotice({ onOpen, onJourney = false }) {
  const [laid, setLaid] = useState([]);
  const hide = useRef(null);
  useEffect(() => {
    const on = (e) => {
      const fresh = Array.isArray(e.detail) ? e.detail : [];
      if (!fresh.length) return;
      // Blocks laid close together (leaving a module can lay several) join one notice.
      setLaid((prev) => [...prev, ...fresh.filter((b) => !prev.some((p) => p.id === b.id))]);
      clearTimeout(hide.current);
      hide.current = setTimeout(() => setLaid([]), SHOW_MS);
    };
    window.addEventListener(LAID_EVENT, on);
    return () => { window.removeEventListener(LAID_EVENT, on); clearTimeout(hide.current); };
  }, []);

  const one = laid.length === 1 ? laid[0] : null;
  return (
    <div aria-live="polite" role="status">
      {laid.length > 0 && (
        <div className="tbn">
          <style>{CSS}</style>
          <span style={{ display: "flex", gap: 3, flexShrink: 0 }}>
            {laid.slice(-5).map((b) => <Mini key={b.id} b={b} />)}
          </span>
          <span style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 1 }}>
            <span style={{ font: `700 0.875rem/1.3 ${T.uiFont}` }}>{one ? "A block for your tower" : "New blocks for your tower"}</span>
            {one && <span style={{ font: `0.75rem/1.3 ${T.uiFont}`, color: T.sub }}>{line(one)}</span>}
          </span>
          {!onJourney && onOpen && (
            <button onClick={() => { setLaid([]); onOpen(); }}>See it</button>
          )}
          <button aria-label="Dismiss" onClick={() => setLaid([])} style={{ fontSize: "1.125rem", padding: "0 8px" }}>×</button>
        </div>
      )}
    </div>
  );
}
